"""SKILL.md validator page (/tools/skill-md-validator/), used by build.py."""
import json

VALIDATE_JS = "// SKILL.md validator: pure function, no DOM. Rules follow the Agent Skills spec\n// (agentskills.io/specification) and Anthropic's \"Create custom skills\" guide.\nfunction validateSkill(text, folder, fileName) {\n  var out = [];\n  function add(level, title, detail) { out.push({ level: level, title: title, detail: detail }); }\n  var SPEC_KEYS = [\"name\", \"description\", \"license\", \"compatibility\", \"metadata\", \"allowed-tools\"];\n\n  if (fileName !== undefined && fileName !== null && fileName.trim() !== \"\" && fileName.trim() !== \"SKILL.md\") {\n    add(\"error\", \"File must be named exactly SKILL.md\",\n      \"You entered \\\"\" + fileName.trim() + \"\\\". The name is case-sensitive: skill.md or Skill.md is not picked up on case-sensitive systems, and you get no error message.\");\n  }\n  if (!text || !text.trim()) { add(\"error\", \"The file is empty\", \"Paste the full contents of your SKILL.md, including the --- frontmatter block.\"); return out; }\n\n  if (text.charCodeAt(0) === 0xFEFF) {\n    add(\"error\", \"File starts with a byte-order mark (BOM)\",\n      \"Some editors on Windows add an invisible BOM character before the first ---. Save the file as \\\"UTF-8\\\" (without BOM).\");\n    text = text.slice(1);\n  }\n  var lines = text.replace(/\\r\\n?/g, \"\\n\").split(\"\\n\");\n  if (lines[0].trim() !== \"---\") {\n    var firstFence = lines.findIndex(function (l) { return l.trim() === \"---\"; });\n    if (firstFence > 0 && lines.slice(0, firstFence).every(function (l) { return !l.trim(); })) {\n      add(\"error\", \"Blank line(s) before the frontmatter\",\n        \"SKILL.md must start with --- on line 1. Delete the \" + firstFence + \" empty line(s) above it.\");\n      lines = lines.slice(firstFence);\n    } else {\n      add(\"error\", \"Missing YAML frontmatter\",\n        \"Line 1 must be --- followed by name: and description: lines, then a closing ---. Without it the skill is not recognized.\");\n      return out;\n    }\n  } else if (lines[0] !== \"---\") {\n    add(\"warn\", \"Extra spaces on the opening --- line\", \"Use exactly three dashes with nothing else on line 1.\");\n  }\n  var end = -1;\n  for (var i = 1; i < lines.length; i++) { if (lines[i].trim() === \"---\") { end = i; break; } }\n  if (end === -1) { add(\"error\", \"Frontmatter is never closed\", \"Add a line with just --- after the description line.\"); return out; }\n\n  var fm = lines.slice(1, end), body = lines.slice(end + 1);\n  var fields = {}, order = [], current = null, blockStyle = false;\n  for (var j = 0; j < fm.length; j++) {\n    var raw = fm[j], ln = j + 2;\n    if (/^\\t/.test(raw) || /^ *\\t/.test(raw)) { add(\"error\", \"Tab character in frontmatter (line \" + ln + \")\", \"YAML does not allow tabs for indentation. Use spaces.\"); continue; }\n    if (!raw.trim() || /^\\s*#/.test(raw)) continue;\n    var m = raw.match(/^([A-Za-z0-9_-]+):(.*)$/);\n    if (m && !/^\\s/.test(raw)) {\n      current = m[1]; var val = m[2];\n      if (fields.hasOwnProperty(current)) add(\"error\", \"Duplicate key \\\"\" + current + \"\\\" (line \" + ln + \")\", \"Each frontmatter key may appear only once.\");\n      order.push(current);\n      var v = val.trim();\n      blockStyle = /^[>|][+-]?$/.test(v);\n      if (blockStyle) { fields[current] = { value: \"\", line: ln, block: true }; continue; }\n      if (/^[\"']/.test(v)) {\n        var q = v[0];\n        if (v.length < 2 || v[v.length - 1] !== q) add(\"error\", \"Unclosed quote in \\\"\" + current + \"\\\" (line \" + ln + \")\", \"The value starts with \" + q + \" but does not end with it on the same line.\");\n        v = v.slice(1, v.length - 1);\n      } else if (/: /.test(v) || /:$/.test(v)) {\n        add(\"error\", \"Unquoted colon in \\\"\" + current + \"\\\" (line \" + ln + \")\",\n          \"A colon followed by a space breaks YAML parsing, so the whole frontmatter can fail to load. Wrap the value in double quotes, e.g. \" + current + \": \\\"\" + v.replace(/\"/g, \"\\\\\\\"\") + \"\\\"\");\n      } else if (/^[\\[{&*!%@`]/.test(v)) {\n        add(\"warn\", \"Value of \\\"\" + current + \"\\\" starts with a special YAML character (line \" + ln + \")\", \"Wrap it in double quotes so it is read as plain text.\");\n      }\n      fields[current] = { value: v, line: ln, block: false };\n    } else if (current && /^\\s+\\S/.test(raw)) {\n      fields[current].value += (fields[current].value ? \" \" : \"\") + raw.trim();\n    } else {\n      add(\"error\", \"Line \" + ln + \" is not valid frontmatter\", \"Expected key: value. Got: \" + raw.trim().slice(0, 60));\n    }\n  }\n\n  // name\n  if (!fields.name) {\n    add(\"warn\", \"No name field\",\n      \"Claude Code falls back to the folder name, but the Agent Skills spec and Claude's upload require name. Add name: \" + (folder ? folder : \"your-skill-name\") + \".\");\n  } else {\n    var name = fields.name.value;\n    if (!name) add(\"error\", \"name is empty\", \"Use 1\u201364 characters: lowercase letters, numbers and hyphens.\");\n    else {\n      if (name.length > 64) add(\"error\", \"name is longer than 64 characters\", \"It has \" + name.length + \" characters.\");\n      if (/[A-Z]/.test(name)) add(\"error\", \"name contains uppercase letters\", \"Only lowercase letters, numbers and hyphens are allowed. Try: \" + name.toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\"));\n      else if (/[^a-z0-9-]/.test(name)) add(\"error\", \"name contains characters that are not allowed\", \"Only a\u2013z, 0\u20139 and hyphens. Spaces and underscores are not allowed. Try: \" + name.toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\"));\n      if (/^-|-$/.test(name)) add(\"error\", \"name starts or ends with a hyphen\", \"Remove the leading or trailing hyphen.\");\n      if (/--/.test(name)) add(\"error\", \"name contains consecutive hyphens\", \"Replace -- with a single hyphen.\");\n      if (/anthropic|claude/i.test(name)) add(\"warn\", \"name contains a reserved word\", \"Names containing \\\"anthropic\\\" or \\\"claude\\\" can be rejected when uploading through the Claude API. Pick a name without them.\");\n      if (/<[^>]+>/.test(name)) add(\"error\", \"name contains an XML/HTML tag\", \"Remove the angle-bracket tag.\");\n      if (folder && folder.trim() && folder.trim() !== name) add(\"error\", \"name does not match the folder name\", \"The folder is \\\"\" + folder.trim() + \"\\\" but name is \\\"\" + name + \"\\\". Anthropic's guide requires them to match. Rename one so they are identical.\");\n    }\n  }\n\n  // description\n  if (!fields.description) {\n    add(\"error\", \"No description field\", \"description is required. Claude reads only the name and description to decide when to load a skill, so without it the skill never triggers on its own.\");\n  } else {\n    var d = fields.description;\n    if (d.block && !d.value) add(\"error\", \"description is empty\", \"The block scalar (> or |) has no indented lines under it.\");\n    else if (!d.value) add(\"error\", \"description is empty\", \"Describe what the skill does and when to use it, in 1\u20131,024 characters.\");\n    else {\n      if (d.value.length > 1024) add(\"error\", \"description is longer than 1,024 characters\", \"It has \" + d.value.length + \". Move details into the body.\");\n      if (/<[^>]+>/.test(d.value)) add(\"warn\", \"description contains an XML/HTML tag\", \"Angle-bracket tags can be rejected by the Claude API. Remove them.\");\n      if (d.value.length < 50) add(\"warn\", \"description is very short (\" + d.value.length + \" characters)\", \"Say what the skill does AND when to use it, using the words people actually type, e.g. \\\"... Use when the user asks to write tests, add unit tests or generate pytest.\\\"\");\n      if (!/\\bwhen\\b|\\bif the user\\b|\\bwhenever\\b/i.test(d.value)) add(\"warn\", \"description does not say when to use the skill\", \"Add a trigger sentence such as \\\"Use when ...\\\". The description is the only part Claude reads before deciding to load the skill.\");\n    }\n  }\n\n  // other keys\n  order.forEach(function (k) {\n    if (SPEC_KEYS.indexOf(k) === -1) add(\"info\", \"Field \\\"\" + k + \"\\\" is not in the Agent Skills spec\", \"Claude Code supports extra fields, so this can be fine there. A strict checker such as skills-ref validate will report it.\");\n  });\n  if (fields.compatibility && fields.compatibility.value.length > 500) add(\"error\", \"compatibility is longer than 500 characters\", \"The spec allows 1\u2013500 characters.\");\n\n  // body\n  var bodyText = body.join(\"\\n\").trim();\n  if (!bodyText) add(\"warn\", \"The body is empty\", \"After the closing ---, add the instructions Claude should follow: steps, rules, output format and an example.\");\n  var bodyLines = body.length;\n  if (bodyLines > 500) add(\"warn\", \"Body is \" + bodyLines + \" lines long\", \"Anthropic recommends keeping SKILL.md under 500 lines and moving reference material into separate files (references/, assets/).\");\n  var abs = bodyText.match(/(?:^|[\\s\"'`(])((?:\\/Users\\/|\\/home\\/)[^\\s\"'`)]+|[A-Za-z]:\\\\\\\\?[^\\s\"'`)]+)/m);\n  if (abs) add(\"warn\", \"Machine-specific path in the instructions\", \"Found \\\"\" + abs[1].slice(0, 60) + \"\\\". It will break on other machines. Use ${CLAUDE_SKILL_DIR}/scripts/... for files inside the skill.\");\n  if (/(api[_-]?key|secret|password|token)\\s*[:=]\\s*[\"']?[A-Za-z0-9_\\-]{16,}/i.test(bodyText)) add(\"error\", \"Possible credential in the file\", \"Never put API keys or passwords in a skill: everyone you share it with receives its files.\");\n\n  if (!out.some(function (r) { return r.level === \"error\" || r.level === \"warn\"; })) add(\"ok\", \"No problems found\", \"Frontmatter parses, name and description follow the spec. Next: copy the folder to ~/.claude/skills/\" + (fields.name && fields.name.value ? fields.name.value : \"<name>\") + \"/ and test it with a real request.\");\n  return out;\n}\n"
UI_JS = "\n(function(){\n  var ta=document.getElementById('sv-text'), fo=document.getElementById('sv-folder'), fn=document.getElementById('sv-file'), out=document.getElementById('sv-out');\n  var icon={error:'\u274c',warn:'\u26a0\ufe0f',info:'\u2139\ufe0f',ok:'\u2705'};\n  var color={error:'#f87171',warn:'#fbbf24',info:'#93c5fd',ok:'#34d399'};\n  function esc(s){return String(s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];});}\n  function run(){\n    var res=validateSkill(ta.value, fo.value, fn.value);\n    var e=res.filter(function(r){return r.level==='error'}).length, w=res.filter(function(r){return r.level==='warn'}).length;\n    var head=e? '<p style=\"font-weight:600;color:#f87171\">'+e+' error'+(e>1?'s':'')+(w?', '+w+' warning'+(w>1?'s':''):'')+'</p>' : (w? '<p style=\"font-weight:600;color:#fbbf24\">'+w+' warning'+(w>1?'s':'')+'</p>' : '');\n    out.innerHTML=head+res.map(function(r){return '<div style=\"border-left:3px solid '+color[r.level]+';padding:8px 12px;margin:8px 0;background:rgba(127,127,127,.08);border-radius:6px\"><strong>'+icon[r.level]+' '+esc(r.title)+'</strong><div style=\"margin-top:4px;opacity:.85\">'+esc(r.detail)+'</div></div>';}).join('');\n  }\n  document.getElementById('sv-run').addEventListener('click',run);\n  document.getElementById('sv-sample').addEventListener('click',function(){\n    ta.value='---\\nname: commit-message\\ndescription: Write a Conventional Commit message from the staged diff: summary line under 72 characters plus a short body. Use when the user asks for a commit message or to commit their changes.\\n---\\n\\n# Commit message\\n\\n1. Run git diff --staged and read the changes.\\n2. Pick the type: feat, fix, docs, refactor, test or chore.\\n3. Write the summary in the imperative mood.\\n';\n    fo.value='commit-message'; run();\n  });\n})();\n"
TOOL_HTML = "<section class=\"hero\" style=\"padding:44px 0 20px\">\n<h1>SKILL.md Validator</h1>\n<p>Check why a Claude Code skill isn't loading. Paste your SKILL.md to validate the frontmatter, name and description against the Agent Skills spec. Runs in your browser, nothing is uploaded.</p>\n</section>\n<section class=\"detail\" style=\"display:block;padding-top:0\">\n<label for=\"sv-text\" style=\"font-weight:600\">SKILL.md contents</label>\n<textarea id=\"sv-text\" spellcheck=\"false\" rows=\"14\" style=\"width:100%;margin:8px 0 12px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;padding:12px;border-radius:8px;border:1px solid rgba(127,127,127,.4);background:rgba(127,127,127,.06);color:inherit\" placeholder=\"---&#10;name: my-skill&#10;description: What it does. Use when ...&#10;---&#10;&#10;Instructions...\"></textarea>\n<div style=\"display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end\">\n<label style=\"flex:1;min-width:200px\">Folder name <span style=\"opacity:.6\">(optional)</span><input id=\"sv-folder\" type=\"text\" placeholder=\"my-skill\" style=\"display:block;width:100%;margin-top:4px;padding:8px;border-radius:6px;border:1px solid rgba(127,127,127,.4);background:transparent;color:inherit\"></label>\n<label style=\"flex:1;min-width:200px\">File name <span style=\"opacity:.6\">(optional)</span><input id=\"sv-file\" type=\"text\" value=\"SKILL.md\" style=\"display:block;width:100%;margin-top:4px;padding:8px;border-radius:6px;border:1px solid rgba(127,127,127,.4);background:transparent;color:inherit\"></label>\n<button id=\"sv-run\" type=\"button\" style=\"padding:10px 18px;border-radius:8px;border:0;background:#34d399;color:#0b0b0f;font-weight:700;cursor:pointer\">Validate</button>\n<button id=\"sv-sample\" type=\"button\" style=\"padding:10px 14px;border-radius:8px;border:1px solid rgba(127,127,127,.45);background:transparent;color:inherit;cursor:pointer\">Try an example</button>\n</div>\n<div id=\"sv-out\" aria-live=\"polite\" style=\"margin-top:16px\"></div>\n</section>\n"
CONTENT_HTML = "<section class=\"detail\" style=\"display:block;padding-top:10px\">\n<h2>What this validator checks</h2>\n<p>Paste the full contents of a <code>SKILL.md</code> file. The check runs entirely in your browser; nothing is uploaded. The rules come from the <a href=\"https://agentskills.io/specification\" rel=\"noopener\">Agent Skills specification</a> and Anthropic's guide to creating custom skills, plus the problems we see most often in public skill repos.</p>\n\n<h3>1. The file starts with valid frontmatter</h3>\n<p>A <code>SKILL.md</code> file must start with YAML frontmatter: a line with <code>---</code>, the <code>name</code> and <code>description</code> fields, and a closing <code>---</code>. If there is a blank line, a heading or an invisible byte-order mark (BOM) before the first <code>---</code>, the frontmatter is not read and the skill does not load. Windows editors sometimes add the BOM; save the file as UTF-8 without BOM.</p>\n\n<h3>2. The YAML actually parses</h3>\n<p>The most common silent failure is an unquoted colon inside the description, such as <code>description: Review code: find bugs</code>. A colon followed by a space starts a new YAML mapping, so the frontmatter fails to parse. Wrap the value in double quotes. Tabs used for indentation, duplicate keys and unclosed quotes break parsing the same way.</p>\n\n<h3>3. The name follows the spec</h3>\n<p><code>name</code> may be 1\u201364 characters of lowercase letters, numbers and hyphens. It must not start or end with a hyphen or contain two hyphens in a row, and it must match the skill's folder name. Claude Code falls back to the folder name when <code>name</code> is missing, but uploading a skill to Claude requires it, so always set it. Names containing \"anthropic\" or \"claude\" can be rejected by the Claude API.</p>\n\n<h3>4. The description tells Claude when to use the skill</h3>\n<p>Claude reads only the name and description of each installed skill until a request matches one. The description is the trigger, not a summary: it should say what the skill does and when to use it, in the words people actually type, and stay within 1,024 characters. A description like \"Design review helper\" rarely fires; \"Run a usability review of screens using Nielsen's heuristics. Use when asked to review, audit or critique a design\" does.</p>\n\n<h3>5. The body is portable and safe</h3>\n<p>Keep <code>SKILL.md</code> under 500 lines and move long reference material into separate files that the instructions point to. Avoid machine-specific paths such as <code>/Users/alice/...</code> or <code>C:\\Users\\...</code>; use <code>${CLAUDE_SKILL_DIR}/scripts/...</code> for files inside the skill. Never put API keys or passwords in a skill, because everyone you share it with receives its files.</p>\n\n<h2>Skill still not loading?</h2>\n<p>If the file passes, check where it lives. In Claude Code the path must be exactly <code>~/.claude/skills/&lt;name&gt;/SKILL.md</code> (or <code>.claude/skills/&lt;name&gt;/SKILL.md</code> inside a project): one folder per skill, not nested one level deeper. The file name is case-sensitive. New skills are picked up automatically; if the <code>skills</code> folder itself did not exist when the session started, run <code>/reload-skills</code>. On Windows, see the <a href=\"/blog/install-claude-code-skills-windows/\">Windows install guide</a>. You can also call a skill directly with <code>/your-skill-name</code> to confirm it is installed.</p>\n\n<h2>FAQ</h2>\n<h3>Is my SKILL.md sent anywhere?</h3>\n<p>No. The validator is plain JavaScript that runs in your browser tab.</p>\n<h3>Does passing mean my skill is good?</h3>\n<p>It means the file is well-formed and follows the spec. Whether the skill improves Claude's output is a separate question: test it on real requests, and when the result goes off, fix the missing or vague line in the skill instead of correcting Claude in chat.</p>\n<h3>Why is a field flagged as \"not in the spec\"?</h3>\n<p>The open specification defines <code>name</code>, <code>description</code>, <code>license</code>, <code>compatibility</code>, <code>metadata</code> and <code>allowed-tools</code>. Claude Code supports extra fields, so those are usually fine there, but strict checkers such as <code>skills-ref validate</code> report them.</p>\n</section>\n"
JSONLD = [{'@context': 'https://schema.org', '@type': 'WebApplication', 'name': 'SKILL.md Validator', 'applicationCategory': 'DeveloperApplication', 'operatingSystem': 'Any', 'offers': {'@type': 'Offer', 'price': '0', 'priceCurrency': 'USD'}, 'url': 'https://skillnest.dev/tools/skill-md-validator/', 'description': 'Validate a Claude Code SKILL.md file against the Agent Skills specification in your browser.'}, {'@context': 'https://schema.org', '@type': 'FAQPage', 'mainEntity': [{'@type': 'Question', 'name': 'Why is my Claude Code skill not loading?', 'acceptedAnswer': {'@type': 'Answer', 'text': 'The most common causes are frontmatter that does not start on line 1, an unquoted colon in the description that breaks YAML parsing, a name that does not match the folder name, or a folder nested one level too deep. The file must be at ~/.claude/skills/<name>/SKILL.md.'}}, {'@type': 'Question', 'name': 'What are the rules for the SKILL.md name field?', 'acceptedAnswer': {'@type': 'Answer', 'text': "1-64 characters of lowercase letters, numbers and hyphens; it must not start or end with a hyphen or contain consecutive hyphens, and it must match the skill's directory name."}}, {'@type': 'Question', 'name': 'How long can a SKILL.md description be?', 'acceptedAnswer': {'@type': 'Answer', 'text': 'Up to 1,024 characters. It should say what the skill does and when to use it, because Claude reads the description to decide when to load the skill.'}}, {'@type': 'Question', 'name': 'Is my SKILL.md uploaded?', 'acceptedAnswer': {'@type': 'Answer', 'text': 'No. The validator runs entirely in your browser.'}}]}]


def render_validator(layout) -> str:
    body = ('<div class="wrap">' + TOOL_HTML + CONTENT_HTML + '</div>'
            + '<script>' + VALIDATE_JS + UI_JS + '</script>')
    extra = "".join('<script type="application/ld+json">' + json.dumps(j, ensure_ascii=False).replace("</", "<\\/") + "</script>" for j in JSONLD)
    return layout(
        title="SKILL.md Validator: Why Isn't My Claude Code Skill Loading? | SkillNest",
        description="Free SKILL.md validator for Claude Code skills. Checks frontmatter, YAML, name and description against the Agent Skills spec in your browser. Nothing is uploaded.",
        body=body,
        canonical="/tools/skill-md-validator/",
        extra_head=extra,
    )
